## Vanilla JS

```js
let debounceTimer;
const searchInput = document.querySelector('input[type="search"]');

searchInput.addEventListener('input', (e) => {
  clearTimeout(debounceTimer);
  debounceTimer = setTimeout(() => {
    fetchResults(e.target.value);
  }, 300);
});

function fetchResults(query) {
  fetch(`/api/search?q=${encodeURIComponent(query)}`)
    .then(r => r.json())
    .then(data => updateUI(data));
}
```

## React

```js
function SearchInput() {
  const [query, setQuery] = useState('');

  useEffect(() => {
    const timer = setTimeout(() => {
      if (query) fetchResults(query);
    }, 300);

    return () => clearTimeout(timer);
  }, [query]);

  return <input onChange={(e) => setQuery(e.target.value)} />;
}
```

## Reusable debounce helper

```js
function debounce(fn, delay) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

// Use it
const debouncedFetch = debounce(fetchResults, 300);
searchInput.addEventListener('input', (e) => debouncedFetch(e.target.value));
```

Pick the first one for inline simplicity, the helper if you need it in multiple places. 300ms is standard; adjust to feel right.
